def transform(grid):
    g = np.array(grid).copy()
    H, W = g.shape
    emit(g.copy(), "Start: 2-seeds on the bottom row, 5s are obstacles.")
    seeds = [x for x in range(W) if g[H-1][x] == 2]
    for sx in seeds:
        y, x = H - 1, sx
        while True:
            if y - 1 < 0:
                break
            if g[y-1][x] == 5:
                if x + 1 >= W or g[y][x+1] == 5:
                    break
                x += 1
            else:
                y -= 1
            g[y][x] = 2
        emit(g.copy(), f"Path from seed at column {sx}: climb up, step right whenever a 5 blocks the way.")
    emit(g.copy(), "All seed paths drawn.")
    return g
